/**
 * // This is ArrayReader's API interface. // You should not implement it, or speculate about its
 * implementation interface ArrayReader { // Compares the sum of arr[l..r] with the sum of arr[x..y]
 * // return 1 if sum(arr[l..r]) > sum(arr[x..y]) // return 0 if sum(arr[l..r]) == sum(arr[x..y]) //
 * return -1 if sum(arr[l..r]) < sum(arr[x..y]) public int compareSub(int l, int r, int x, int y) {}
 *
 * <p>// Returns the length of the array public int length() {} }
 */
class Solution {
  public int getIndex(ArrayReader reader) {

    int start = 0;
    int end = reader.length() - 1;
    while ((start + 1) < end) {
      int mid = (end + start) / 2;
      int midS = end - mid > mid - start ? mid + 1 : mid;

      int result = reader.compareSub(start, mid, midS, end);

      if (result == 1) {

        end = mid;
      } else if (result == -1) {
        start = mid;
      } else if (result == 0) {
        return mid;
      }
    }

    int result = reader.compareSub(start, start, end, end);
    return result == 1 ? start : end;
  }
}
